<?php
namespace App\Http\Controllers;use App\Models\{Document,Brand};use Illuminate\Http\Request;use Illuminate\Support\Facades\Storage;
class ResourceController extends Controller {public function index(Request $r){$q=Document::with(['brand','product'])->where('status',1);if($r->type)$q->where('document_type',$r->type);if($r->brand)$q->whereHas('brand',fn($x)=>$x->where('slug',$r->brand));if($r->q)$q->where('title','like','%'.$r->q.'%');return view('resources.index',['documents'=>$q->latest()->paginate(18)->withQueryString(),'brands'=>Brand::where('status',1)->get()]);}public function download(Document $document){abort_unless($document->status,404);$document->increment('downloads');if($document->external_url)return redirect()->away($document->external_url);abort_unless($document->file_path&&Storage::disk('public')->exists($document->file_path),404);return Storage::disk('public')->download($document->file_path);}}
